CREATE TABLE `payroll` (
  `payroll_id` int NOT NULL AUTO_INCREMENT,
  `employeeId` int NOT NULL,
  `pay_period_start` date NOT NULL,
  `pay_period_end` date NOT NULL,
  `total_working_hours` decimal(8,2) NOT NULL,
  `basic_salary` decimal(12,2) NOT NULL,
  `advance_deduction` decimal(12,2) NOT NULL DEFAULT '0.00',
  `net_salary` decimal(12,2) NOT NULL,
  `payment_date` date DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  `base_salary` decimal(12,2) DEFAULT NULL,
  `monthly_expected_hours` decimal(8,2) DEFAULT NULL,
  `salary_rate_per_hour` decimal(10,2) DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNPAID',
  `scheduled_payment_date` date DEFAULT NULL,
  `extra_hours` decimal(8,2) NOT NULL DEFAULT '0.00',
  `incentive_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `regular_working_hours` decimal(8,2) NOT NULL DEFAULT '0.00',
  `shortage_deduction` decimal(12,2) NOT NULL DEFAULT '0.00',
  `shortage_hours` decimal(8,2) NOT NULL DEFAULT '0.00',
  `paid_holiday_hours` decimal(8,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`payroll_id`),
  KEY `payroll_employeeId_idx` (`employeeId`),
  KEY `payroll_pay_period_start_pay_period_end_idx` (`pay_period_start`,`pay_period_end`),
  KEY `payroll_status_idx` (`status`),
  KEY `payroll_scheduled_payment_date_idx` (`scheduled_payment_date`),
  CONSTRAINT `payroll_employeeId_fkey` FOREIGN KEY (`employeeId`) REFERENCES `employees` (`employee_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
